func main() {
	gin.SetMode(gin.ReleaseMode)

	// 不建路由，只造一个 Context 直接调 handler
	c, _ := gin.CreateTestContext(httptest.NewRecorder())
	c.Request = httptest.NewRequest("GET", "/?name=tom", nil)
	c.Set("uid", 42)

	uid, _ := c.Get("uid")
	// Query 读的是 c.Request，所以 Request 必须自己赋值
	fmt.Println("uid:", uid, "name:", c.Query("name"))
	fmt.Println("状态码:", c.Writer.Status())
}

