func BenchmarkPing(b *testing.B) {
	r := gin.New()
	r.GET("/ping", func(c *gin.Context) { c.String(http.StatusOK, "pong") })
	req := httptest.NewRequest(http.MethodGet, "/ping", nil)

	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		// Recorder 每次新建，否则 header 和 body 会跨轮累积
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
	}
}

