import (
	"sync"
	"testing"
)

func TestConcurrent(t *testing.T) {
	var counter int
	var wg sync.WaitGroup
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			counter++ // 两个 goroutine 同时写，go test -race 会报 data race
		}()
	}
	wg.Wait()
	if counter != 2 {
		t.Errorf("counter = %d, want 2", counter)
	}
}

